import os
import time
from typing import Any, Dict, List, Optional

import assemblyai as aai


def _normalize_utterances(transcript: Any) -> List[Dict[str, Any]]:
    utterances = getattr(transcript, "utterances", None) or []
    normalized = []
    for u in utterances:
        normalized.append(
            {
                "speaker": getattr(u, "speaker", None),
                "text": getattr(u, "text", None),
                "start": getattr(u, "start", None),
                "end": getattr(u, "end", None),
            }
        )
    return normalized


def transcribe_meeting_with_speaker_diarization(
    audio_url: str,
    *,
    wait_for_completion: bool = True,
    poll_interval_seconds: int = 5,
    timeout_seconds: Optional[int] = None,
) -> Dict[str, Any]:
    api_key = os.environ.get("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise EnvironmentError("ASSEMBLYAI_API_KEY is required")

    aai.settings.api_key = api_key

    config = aai.TranscriptionConfig(
        speaker_labels=True,
        auto_chapters=False,
        format_text=True,
        punctuate=True,
    )

    transcript = aai.Transcriber().transcribe(audio_url, config)

    if wait_for_completion:
        start_time = time.time()
        while transcript.status not in ("completed", "error"):
            if timeout_seconds is not None and (time.time() - start_time) > timeout_seconds:
                raise TimeoutError("Transcription timed out")
            time.sleep(poll_interval_seconds)
            transcript = aai.Transcript.get_by_id(transcript.id)

    if transcript.status == "error":
        raise RuntimeError(f"AssemblyAI transcription failed: {getattr(transcript, 'error', 'unknown error')}")

    return {
        "id": transcript.id,
        "status": transcript.status,
        "text": getattr(transcript, "text", None),
        "utterances": _normalize_utterances(transcript),
    }
